/* Public question bank: 48 scenario questions, 4 per module, trilingual (en/bn/fr). Answer index a is shared across languages. MINUKA and the Republic of Karana are fictional. */
TRACK.qbank = [
 /* ---------- m1 FOUNDATIONS ---------- */
 {m:"m1", a:2,
  en:{q:"A new MINUKA officer asks for the 2019 Policy’s official definition of peacekeeping-intelligence for a briefing slide. What is the accurate reply?", o:["Quote the definition in the Policy’s Terms section, since every term used there is defined word for word","Use the definition of a national intelligence service","It has no stand-alone definition; teach its purpose","Use the Security Council’s definition from resolution 2295"], e:"The Policy’s Terms section defines the cycle, products and related terms, but not PKI itself. Teach it from the purpose in para 5 and the difference between information and assessment."},
  bn:{q:"মিনুকার একজন নতুন কর্মকর্তা ব্রিফিং স্লাইডের জন্য ২০১৯ নীতিতে শান্তিরক্ষা-গোয়েন্দা তথ্যের দাপ্তরিক সংজ্ঞা চাইলেন। সঠিক উত্তর কী?", o:["নীতির পরিভাষা অংশের সংজ্ঞা হুবহু উদ্ধৃত করুন, কারণ সেখানে ব্যবহৃত প্রতিটি পরিভাষা শব্দে শব্দে সংজ্ঞায়িত","কোনো জাতীয় গোয়েন্দা সংস্থার সংজ্ঞা ব্যবহার করুন","পৃথক সংজ্ঞা নেই; এর উদ্দেশ্য শেখান","প্রস্তাব ২২৯৫-এ নিরাপত্তা পরিষদের সংজ্ঞা ব্যবহার করুন"], e:"নীতির পরিভাষা অংশে চক্র, পণ্য ও সংশ্লিষ্ট পরিভাষার সংজ্ঞা আছে, কিন্তু PKI-এর নিজের নেই। অনুচ্ছেদ ৫-এর উদ্দেশ্য এবং তথ্য ও মূল্যায়নের পার্থক্য দিয়ে এটি শেখান।"},
  fr:{q:"Un nouvel officier de la MINUKA demande la définition officielle du renseignement dans la Politique de 2019 pour une diapositive. Quelle réponse est exacte ?", o:["Citer la définition de la section Terminologie, car chaque terme employé y est défini mot pour mot","Reprendre la définition d’un service national de renseignement","Pas de définition autonome ; enseigner sa finalité","Reprendre la définition du Conseil de sécurité dans la résolution 2295"], e:"La section Terminologie définit le cycle, les produits et des termes voisins, mais pas le PKI lui-même. Enseignez-le à partir de la finalité (par. 5) et de la distinction entre information et évaluation."}},
 {m:"m1", a:0,
  en:{q:"A MINUKA patrol reports: “Three trucks crossed the Lemu bridge at 0600.” How should this line be classed?", o:["Information, not yet an assessment","A finished peacekeeping-intelligence product, because a trained patrol observed it directly and reported it the same day","A clandestine acquisition","A Priority Intelligence Requirement"], e:"The Military PKI Handbook separates information, the factual report of events, from PKI, the assessment derived from analysing it."},
  bn:{q:"মিনুকার একটি টহল দল জানাল: “ভোর ৬টায় তিনটি ট্রাক লেমু সেতু পার হয়েছে।” এই বাক্যকে কীভাবে শ্রেণিভুক্ত করবেন?", o:["তথ্য, এখনও মূল্যায়ন নয়","একটি সম্পূর্ণ শান্তিরক্ষা-গোয়েন্দা তথ্য পণ্য, কারণ প্রশিক্ষিত টহল দল সরাসরি দেখে একই দিনে প্রতিবেদন দিয়েছে","গোপন সংগ্রহ","অগ্রাধিকারভিত্তিক গোয়েন্দা তথ্য চাহিদা"], e:"সামরিক PKI হ্যান্ডবুক তথ্যকে (ঘটনার তথ্যভিত্তিক বিবরণ) PKI থেকে আলাদা করে; PKI হলো তা বিশ্লেষণ করে পাওয়া মূল্যায়ন।"},
  fr:{q:"Une patrouille de la MINUKA signale : « Trois camions ont franchi le pont de Lemu à 6 h. » Comment classer cette phrase ?", o:["Une information, pas encore une évaluation","Un produit de renseignement achevé, car une patrouille formée l’a observé directement et signalé le jour même","Une acquisition clandestine","Un besoin prioritaire en renseignement"], e:"Le manuel militaire distingue l’information, compte rendu factuel des événements, du PKI, évaluation issue de son analyse."}},
 {m:"m1", a:3,
  en:{q:"A sensitive daily situation report at MINUKA was never tasked or handled in the PKI cycle. Does the PKI Policy govern it?", o:["Yes, because any sensitive mission document automatically becomes peacekeeping-intelligence under the Policy","Yes, if a military officer wrote it","Only after the Security Council is told","No: the Policy covers only material in the cycle"], e:"Policy para 8: the Policy applies only to material managed in the PKI cycle. Routine reporting is distinct, even when sensitive."},
  bn:{q:"মিনুকার একটি সংবেদনশীল দৈনিক পরিস্থিতি প্রতিবেদন কখনো PKI চক্রে দায়িত্ব দেওয়া বা পরিচালিত হয়নি। PKI নীতি কি এতে প্রযোজ্য?", o:["হ্যাঁ, কারণ যেকোনো সংবেদনশীল মিশন দলিল নীতির অধীনে স্বয়ংক্রিয়ভাবে শান্তিরক্ষা-গোয়েন্দা তথ্য হয়ে যায়","হ্যাঁ, যদি কোনো সামরিক কর্মকর্তা লিখে থাকেন","কেবল নিরাপত্তা পরিষদকে জানানোর পর","না: নীতি কেবল চক্রের উপকরণে প্রযোজ্য"], e:"নীতির অনুচ্ছেদ ৮: এটি কেবল PKI চক্রে পরিচালিত উপকরণে প্রযোজ্য। নিয়মিত প্রতিবেদন সংবেদনশীল হলেও আলাদা।"},
  fr:{q:"Un rapport de situation quotidien sensible de la MINUKA n’a jamais été traité dans le cycle PKI. La Politique PKI le régit-elle ?", o:["Oui, car tout document sensible de la mission devient automatiquement du renseignement au sens de la Politique","Oui, si un officier militaire l’a rédigé","Seulement après information du Conseil de sécurité","Non : seule la matière du cycle est couverte"], e:"Politique, par. 8 : elle ne s’applique qu’aux éléments gérés dans le cycle PKI. Les rapports courants en sont distincts, même sensibles."}},
 {m:"m1", a:1,
  en:{q:"A MINUKA trainer wants to tell the class how current the 2019 PKI Policy is. Which statement is safest?", o:["It is certainly in force and unchanged, because the review date in the document guarantees its continued validity","It is the latest version found; check current UN guidance","It was replaced in 2021","It lapsed when its review date passed"], e:"No revision was found and 2025 guidance still cites it, but its review date passed in 2021 and internal UN pages could not be checked. Say so and check current guidance."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক ক্লাসে জানাতে চান ২০১৯ সালের PKI নীতি কতটা হালনাগাদ। কোন বক্তব্য সবচেয়ে নিরাপদ?", o:["এটি নিশ্চিতভাবে কার্যকর ও অপরিবর্তিত, কারণ দলিলের পর্যালোচনার তারিখই এর অব্যাহত বৈধতার নিশ্চয়তা দেয়","এটি পাওয়া সর্বশেষ সংস্করণ; বর্তমান নির্দেশনা দেখুন","২০২১ সালে এটি প্রতিস্থাপিত হয়েছে","পর্যালোচনার তারিখ পার হওয়ায় এটি বাতিল"], e:"কোনো সংশোধিত সংস্করণ পাওয়া যায়নি এবং ২০২৫ সালের নির্দেশনাও এটি উদ্ধৃত করে, তবে পর্যালোচনার তারিখ ২০২১ সালে পার হয়েছে এবং জাতিসংঘের অভ্যন্তরীণ পাতা দেখা যায়নি। তা বলুন এবং বর্তমান নির্দেশনা যাচাই করুন।"},
  fr:{q:"Un formateur de la MINUKA veut indiquer à quel point la Politique PKI de 2019 est à jour. Quelle affirmation est la plus prudente ?", o:["Elle est assurément en vigueur et inchangée, car sa date de révision garantit qu’elle reste valable","C’est la dernière version trouvée ; vérifier les orientations actuelles","Elle a été remplacée en 2021","Elle est caduque depuis sa date de révision"], e:"Aucune révision n’a été trouvée et les orientations de 2025 la citent encore, mais sa date de révision est passée en 2021 et les pages internes n’ont pu être consultées. Dites-le et vérifiez."}},
 /* ---------- m2 RULES ---------- */
 {m:"m2", a:1,
  en:{q:"A MINUKA officer proposes going to the Oru market in plain clothes, hiding that he works for the UN, to hear what people say. What should happen?", o:["Approve it if the Force Commander signs, since a senior signature makes concealment acceptable in a protection emergency","Stop and refer it: this crosses the non-clandestine line","Allow it once only","Allow it if no notes are taken"], e:"Concealing UN employment or identity is outside the boundaries of PKI (Policy para 9; HPKI 12.5). No urgency or signature changes that."},
  bn:{q:"মিনুকার একজন কর্মকর্তা প্রস্তাব দিলেন, তিনি সাদা পোশাকে জাতিসংঘের চাকরি গোপন রেখে ওরু বাজারে গিয়ে মানুষের কথা শুনবেন। কী হওয়া উচিত?", o:["ফোর্স কমান্ডার স্বাক্ষর করলে অনুমোদন দিন, কারণ সুরক্ষা জরুরি অবস্থায় জ্যেষ্ঠ স্বাক্ষর গোপনীয়তাকে গ্রহণযোগ্য করে","থামান ও জানান: এটি অ-গোপনীয়তার সীমা অতিক্রম করে","কেবল একবার অনুমতি দিন","নোট না নিলে অনুমতি দিন"], e:"জাতিসংঘের চাকরি বা পরিচয় গোপন করা PKI-এর সীমার বাইরে (নীতি অনু. ৯; HPKI ১২.৫)। জরুরি অবস্থা বা স্বাক্ষর এতে কিছু বদলায় না।"},
  fr:{q:"Un officier de la MINUKA propose d’aller au marché d’Oru en civil, en cachant qu’il travaille pour l’ONU, pour écouter les gens. Que faire ?", o:["Approuver si le commandant de la force signe, car une signature supérieure rend la dissimulation acceptable en cas d’urgence","Arrêter et saisir la hiérarchie : ligne non clandestine franchie","Autoriser une seule fois","Autoriser si aucune note n’est prise"], e:"Dissimuler son emploi à l’ONU ou son identité sort du cadre du PKI (Politique, par. 9 ; HPKI 12.5). Ni l’urgence ni une signature n’y changent rien."}},
 {m:"m2", a:3,
  en:{q:"A MINUKA battalion’s home capital asks its S2 for a private copy of a mission assessment. Which principle answers this first?", o:["Areas of application, because a national capital’s interest counts as the safety of UN personnel in every case","Host-State sovereignty","Need to know, which allows it","Independence: PKI is autonomous from national systems"], e:"Independence: mission PKI is fully autonomous from any national intelligence system and has an exclusively international character. Refer the request through the mission’s channels."},
  bn:{q:"মিনুকার একটি ব্যাটালিয়নের নিজ দেশের রাজধানী তার S2-এর কাছে মিশনের একটি মূল্যায়নের ব্যক্তিগত কপি চাইল। কোন নীতি প্রথমে এর উত্তর দেয়?", o:["প্রয়োগের ক্ষেত্র, কারণ জাতীয় রাজধানীর আগ্রহ সব ক্ষেত্রেই জাতিসংঘ কর্মীদের নিরাপত্তা হিসেবে গণ্য হয়","আয়োজক রাষ্ট্রের সার্বভৌমত্ব","জানার প্রয়োজন, যা এটি অনুমোদন করে","স্বাধীনতা: PKI জাতীয় ব্যবস্থা থেকে স্বতন্ত্র"], e:"স্বাধীনতা: মিশনের PKI যেকোনো জাতীয় গোয়েন্দা ব্যবস্থা থেকে সম্পূর্ণ স্বায়ত্তশাসিত এবং একান্তভাবে আন্তর্জাতিক। অনুরোধটি মিশনের চ্যানেলে পাঠান।"},
  fr:{q:"La capitale d’origine d’un bataillon de la MINUKA demande à son S2 une copie privée d’une évaluation de la mission. Quel principe répond d’abord ?", o:["Les domaines d’application, car l’intérêt d’une capitale compte toujours comme sécurité du personnel de l’ONU","La souveraineté de l’État hôte","Le besoin d’en connaître, qui l’autorise","L’indépendance : le PKI est autonome des systèmes nationaux"], e:"Indépendance : le PKI de la mission est pleinement autonome de tout système national et a un caractère exclusivement international. Renvoyez la demande aux voies de la mission."}},
 {m:"m2", a:0,
  en:{q:"A MINUKA planner suggests using an assessment of Karana’s army as pressure on its government during a dispute. What rule applies?", o:["PKI is not to be used against or to threaten the Host State","It is acceptable when the mission’s mandate is under pressure and the government is in clear breach of its obligations","Permitted with Force Commander approval","Permitted if the assessment is accurate"], e:"The Military PKI Handbook states that PKI is not to be used against or to threaten Host or neighbouring States; the Policy’s sovereignty principle covers both."},
  bn:{q:"মিনুকার একজন পরিকল্পনাকারী বিরোধের সময় কারানার সেনাবাহিনী সম্পর্কিত মূল্যায়নকে তার সরকারের ওপর চাপ হিসেবে ব্যবহারের পরামর্শ দিলেন। কোন নিয়ম প্রযোজ্য?", o:["PKI আয়োজক রাষ্ট্রের বিরুদ্ধে বা হুমকিতে ব্যবহার করা যাবে না","মিশনের ম্যান্ডেট চাপে থাকলে এবং সরকার স্পষ্টভাবে দায়িত্ব লঙ্ঘন করলে এটি গ্রহণযোগ্য","ফোর্স কমান্ডারের অনুমোদনে অনুমোদিত","মূল্যায়ন নির্ভুল হলে অনুমোদিত"], e:"সামরিক PKI হ্যান্ডবুক বলে, PKI আয়োজক বা প্রতিবেশী রাষ্ট্রের বিরুদ্ধে বা হুমকিতে ব্যবহার করা যাবে না; নীতির সার্বভৌমত্ব মূলনীতি উভয়কেই অন্তর্ভুক্ত করে।"},
  fr:{q:"Un planificateur de la MINUKA suggère d’utiliser une évaluation de l’armée de Karana pour faire pression sur son gouvernement lors d’un différend. Quelle règle s’applique ?", o:["Le PKI ne sert ni contre l’État hôte ni à le menacer","C’est acceptable lorsque le mandat est sous pression et que le gouvernement manque clairement à ses obligations","Permis avec l’accord du commandant de la force","Permis si l’évaluation est exacte"], e:"Le manuel militaire précise que le PKI ne doit pas être utilisé contre les États hôtes ou voisins ni pour les menacer ; le principe de souveraineté de la Politique couvre les deux."}},
 {m:"m2", a:2,
  en:{q:"A MINUKA official asks JMAC to task a PKI report on a lawful opposition party’s fundraising, with no safety or protection link. What is the best response?", o:["Accept, because political analysis of any kind automatically falls within the Policy’s areas of application","Accept if the party is told afterwards","Decline as PKI: it is outside the areas of application","Accept, but mark it Strictly Confidential"], e:"PKI applies to situational awareness, the safety and security of UN personnel, and protection of civilians tasks. The rights to privacy and association also point against it."},
  bn:{q:"মিনুকার একজন কর্মকর্তা JMAC-কে একটি বৈধ বিরোধী দলের তহবিল সংগ্রহ নিয়ে PKI প্রতিবেদনের দায়িত্ব দিতে চাইলেন, যার সঙ্গে নিরাপত্তা বা সুরক্ষার সম্পর্ক নেই। সেরা উত্তর কী?", o:["গ্রহণ করুন, কারণ যেকোনো রাজনৈতিক বিশ্লেষণ স্বয়ংক্রিয়ভাবে নীতির প্রয়োগের ক্ষেত্রে পড়ে","দলটিকে পরে জানানো হলে গ্রহণ করুন","PKI হিসেবে প্রত্যাখ্যান করুন: এটি প্রয়োগের ক্ষেত্রের বাইরে","গ্রহণ করুন, তবে Strictly Confidential চিহ্নিত করুন"], e:"PKI পরিস্থিতিগত সচেতনতা, জাতিসংঘ কর্মীদের নিরাপত্তা ও বেসামরিক সুরক্ষার কাজে প্রযোজ্য। গোপনীয়তা ও সংগঠনের অধিকারও এর বিরুদ্ধে যায়।"},
  fr:{q:"Un responsable de la MINUKA demande au JMAC un rapport PKI sur le financement d’un parti d’opposition légal, sans lien avec la sécurité ou la protection. Quelle est la meilleure réponse ?", o:["Accepter, car toute analyse politique relève automatiquement des domaines d’application de la Politique","Accepter si le parti en est informé ensuite","Refuser comme PKI : hors des domaines d’application","Accepter, mais marquer Strictly Confidential"], e:"Le PKI s’applique à la connaissance de la situation, à la sûreté et à la sécurité du personnel et à la protection des civils. Les droits à la vie privée et d’association vont aussi contre cette demande."}},
 /* ---------- m3 ARCHITECTURE ---------- */
 {m:"m3", a:0,
  en:{q:"After a poor decision at MINUKA, who is accountable for the mission’s PKI system?", o:["The Head of Mission","The Chief JMAC alone, because that office drafts the plans and therefore carries all responsibility for the system","The troop-contributing countries","UNDSS"], e:"The Head of Mission is accountable for the system, ultimately to the Secretary-General, and is its primary client."},
  bn:{q:"মিনুকায় একটি দুর্বল সিদ্ধান্তের পর মিশনের PKI ব্যবস্থার জন্য কে জবাবদিহি করবেন?", o:["মিশন প্রধান","কেবল JMAC প্রধান, কারণ ওই দপ্তর পরিকল্পনা লেখে এবং তাই ব্যবস্থার সব দায় তার","সৈন্য প্রদানকারী দেশগুলো","UNDSS"], e:"মিশন প্রধান এই ব্যবস্থার জন্য জবাবদিহি করেন, চূড়ান্তভাবে মহাসচিবের কাছে, এবং তিনিই এর প্রধান ব্যবহারকারী।"},
  fr:{q:"Après une mauvaise décision à la MINUKA, qui répond du système PKI de la mission ?", o:["Le chef de mission","Le chef du JMAC seul, car ce bureau rédige les plans et porte donc toute la responsabilité du système","Les pays fournisseurs de contingents","L’UNDSS"], e:"Le chef de mission répond du système, en dernier ressort devant le Secrétaire général, et en est le principal client."}},
 {m:"m3", a:2,
  en:{q:"The MICM Chair at MINUKA tells members to write the threat analysis together in the meeting. What is wrong?", o:["Nothing: writing all analysis is the Mechanism’s central function under the 2019 Policy and the Handbook","Only the Force may analyse","The Mechanism directs and oversees; it does not analyse","Only UNHQ may analyse"], e:"Policy 12.3: the Mechanism directs and oversees the cycle and does not conduct analysis. That belongs to entities such as JMAC and the U2."},
  bn:{q:"মিনুকার MICM সভাপতি সদস্যদের সভাতেই একসঙ্গে হুমকি বিশ্লেষণ লিখতে বললেন। ভুল কোথায়?", o:["কিছুই নয়: ২০১৯ নীতি ও হ্যান্ডবুক অনুযায়ী সব বিশ্লেষণ লেখাই এই ব্যবস্থার কেন্দ্রীয় কাজ","কেবল ফোর্স বিশ্লেষণ করতে পারে","এটি পরিচালনা ও তদারকি করে; বিশ্লেষণ করে না","কেবল UNHQ বিশ্লেষণ করতে পারে"], e:"নীতি ১২.৩: এই ব্যবস্থা চক্র পরিচালনা ও তদারকি করে, বিশ্লেষণ করে না। সে কাজ JMAC ও U2-এর মতো সত্তার।"},
  fr:{q:"Le président du MICM de la MINUKA demande aux membres de rédiger ensemble l’analyse de la menace en séance. Quel est le problème ?", o:["Aucun : rédiger toutes les analyses est la fonction centrale du Mécanisme selon la Politique de 2019 et le manuel","Seule la force peut analyser","Le Mécanisme dirige et supervise ; il n’analyse pas","Seul le Siège peut analyser"], e:"Politique 12.3 : le Mécanisme dirige et supervise le cycle sans effectuer d’analyse. Celle-ci revient à des entités comme le JMAC et l’U2."}},
 {m:"m3", a:3,
  en:{q:"A MINUKA battalion commander needs assessments on short timelines for tomorrow’s patrols. Which staff supports this commander directly?", o:["The U2, since Force headquarters staff work directly for every battalion commander in the mission area","The G2","The UNOCC","The S2"], e:"U2 serves Force HQ, G2 the Sector, and S2 the Battalion. The S2 works to shorter timelines and directs company-level needs."},
  bn:{q:"মিনুকার একজন ব্যাটালিয়ন কমান্ডারের আগামীকালের টহলের জন্য স্বল্প সময়ে মূল্যায়ন দরকার। কোন স্টাফ তাঁকে সরাসরি সহায়তা করে?", o:["U2, কারণ ফোর্স সদর দপ্তরের স্টাফ মিশন এলাকার প্রতিটি ব্যাটালিয়ন কমান্ডারের জন্য সরাসরি কাজ করে","G2","UNOCC","S2"], e:"U2 ফোর্স সদর দপ্তরে, G2 সেক্টরে এবং S2 ব্যাটালিয়নে। S2 স্বল্প সময়সীমায় কাজ করে এবং কোম্পানি পর্যায়ের চাহিদা পরিচালনা করে।"},
  fr:{q:"Un commandant de bataillon de la MINUKA a besoin d’évaluations à court délai pour les patrouilles de demain. Quel personnel l’appuie directement ?", o:["L’U2, car le personnel du QG de la force travaille directement pour chaque commandant de bataillon de la zone","Le G2","L’UNOCC","Le S2"], e:"L’U2 sert au QG de la force, le G2 au secteur et le S2 au bataillon. Le S2 travaille à court délai et dirige les besoins au niveau de la compagnie."}},
 {m:"m3", a:1,
  en:{q:"A MINUKA staff paper calls for an ASIFU because it is “the UN standard structure.” How should you correct it?", o:["It is correct, as every 2025 handbook makes the ASIFU a compulsory part of each mission’s military component","ASIFU is historic (MINUSMA), not a current standard","ASIFU replaced JMAC in 2019","ASIFU is a UNHQ office"], e:"The All Source Information Fusion Unit was a Mali practice example. The term does not appear in the UN guidance read for this course, including the 2025 handbooks."},
  bn:{q:"মিনুকার একটি স্টাফ পত্রে ASIFU চাওয়া হয়েছে, কারণ এটি নাকি “জাতিসংঘের আদর্শ কাঠামো।” কীভাবে সংশোধন করবেন?", o:["এটি সঠিক, কারণ ২০২৫ সালের প্রতিটি হ্যান্ডবুক ASIFU-কে প্রতিটি মিশনের সামরিক অংশের বাধ্যতামূলক অংশ করেছে","ASIFU ঐতিহাসিক (MINUSMA), বর্তমান আদর্শ নয়","২০১৯ সালে ASIFU JMAC-এর স্থান নেয়","ASIFU একটি UNHQ দপ্তর"], e:"All Source Information Fusion Unit মালির একটি চর্চার উদাহরণ ছিল। এই কোর্সের জন্য পড়া জাতিসংঘের নির্দেশনায়, ২০২৫ সালের হ্যান্ডবুকসহ, পরিভাষাটি নেই।"},
  fr:{q:"Une note de la MINUKA réclame une ASIFU comme « structure standard de l’ONU ». Comment corriger ?", o:["C’est exact, car chaque manuel de 2025 fait de l’ASIFU un élément obligatoire de la composante militaire de chaque mission","L’ASIFU est historique (MINUSMA), non une norme actuelle","L’ASIFU a remplacé le JMAC en 2019","L’ASIFU est un bureau du Siège"], e:"L’All Source Information Fusion Unit était un exemple de pratique au Mali. Le terme n’apparaît pas dans les orientations de l’ONU lues pour ce cours, y compris les manuels de 2025."}},
 /* ---------- m4 DIRECTION ---------- */
 {m:"m4", a:3,
  en:{q:"A MINUKA trainer’s old slide shows a four-stage cycle from the 2019 Handbook. What should the class learn?", o:["Four stages, because the earlier Handbook edition takes priority over both the Policy and the later edition","Three stages: ask, find, tell","Six stages, adding evaluation","Five: direction, acquisition, examination and collation, analysis, dissemination"], e:"The Policy and the 2025 Military PKI Handbook both have five stages. The superseded 2019 Handbook had four."},
  bn:{q:"মিনুকার এক প্রশিক্ষকের পুরোনো স্লাইডে ২০১৯ সালের হ্যান্ডবুকের চার ধাপের চক্র আছে। ক্লাসে কী শেখা উচিত?", o:["চার ধাপ, কারণ আগের হ্যান্ডবুক সংস্করণ নীতি ও পরের সংস্করণ উভয়ের ওপর অগ্রাধিকার পায়","তিন ধাপ: জিজ্ঞাসা, অনুসন্ধান, জানানো","ছয় ধাপ, মূল্যায়নসহ","পাঁচ: নির্দেশনা, সংগ্রহ, পরীক্ষা ও সমন্বয়, বিশ্লেষণ, বিতরণ"], e:"নীতি ও ২০২৫ সালের সামরিক PKI হ্যান্ডবুক উভয়েই পাঁচ ধাপ আছে। রহিত ২০১৯ হ্যান্ডবুকে ছিল চার।"},
  fr:{q:"Une ancienne diapositive d’un formateur de la MINUKA montre un cycle à quatre étapes tiré du manuel de 2019. Que doit apprendre la classe ?", o:["Quatre étapes, car l’édition antérieure du manuel prime à la fois sur la Politique et sur l’édition suivante","Trois étapes : demander, trouver, dire","Six étapes, avec l’évaluation","Cinq : direction, acquisition, examen et collation, analyse, diffusion"], e:"La Politique et le manuel militaire de 2025 comptent cinq étapes. Le manuel de 2019, remplacé, en comptait quatre."}},
 {m:"m4", a:1,
  en:{q:"A MINUKA requirements list has not changed in two years and consists of topic headings. What does the Policy expect?", o:["Nothing further, because requirements are permanent once the Head of Mission has approved them for the first time","Requirements usually phrased as questions, reviewed at least annually","Requirements set only by UNHQ","Requirements kept secret from the MICM"], e:"Policy 12.9: Information Requirements are usually phrased as questions and reviewed at least annually."},
  bn:{q:"মিনুকার চাহিদা তালিকা দুই বছর বদলায়নি এবং কেবল বিষয়ের শিরোনামে ভরা। নীতি কী প্রত্যাশা করে?", o:["আর কিছু নয়, কারণ মিশন প্রধান প্রথমবার অনুমোদন করলেই চাহিদা স্থায়ী হয়ে যায়","চাহিদা সাধারণত প্রশ্ন আকারে, অন্তত বছরে একবার পর্যালোচিত","কেবল UNHQ চাহিদা নির্ধারণ করবে","চাহিদা MICM থেকে গোপন থাকবে"], e:"নীতি ১২.৯: তথ্য চাহিদা সাধারণত প্রশ্ন আকারে লেখা হয় এবং অন্তত বছরে একবার পর্যালোচনা করা হয়।"},
  fr:{q:"La liste des besoins de la MINUKA n’a pas changé depuis deux ans et ne contient que des titres de sujets. Qu’attend la Politique ?", o:["Rien de plus, car les besoins deviennent permanents dès la première approbation par le chef de mission","Des besoins formulés en questions, revus au moins chaque année","Des besoins fixés par le Siège seul","Des besoins cachés au MICM"], e:"Politique 12.9 : les besoins d’information sont généralement formulés en questions et revus au moins une fois par an."}},
 {m:"m4", a:0,
  en:{q:"Who leads the drafting of MINUKA’s Mission Information Acquisition Plan and Support Plan?", o:["JMAC, with validation by the MICM","The Force Commander’s personal staff, since acquisition is a purely military matter under the Handbook","The Host State’s army","Each patrol leader"], e:"Policy 12.6: JMAC is tasked to lead drafting of both plans, and the Mechanism validates them."},
  bn:{q:"মিনুকার মিশন তথ্য সংগ্রহ পরিকল্পনা ও সহায়তা পরিকল্পনার খসড়া তৈরিতে নেতৃত্ব দেয় কে?", o:["JMAC, MICM-এর অনুমোদনসহ","ফোর্স কমান্ডারের ব্যক্তিগত স্টাফ, কারণ হ্যান্ডবুক অনুযায়ী সংগ্রহ একান্তই সামরিক বিষয়","আয়োজক রাষ্ট্রের সেনাবাহিনী","প্রত্যেক টহল নেতা"], e:"নীতি ১২.৬: উভয় পরিকল্পনার খসড়ায় নেতৃত্ব দেয় JMAC, এবং এই ব্যবস্থা তা অনুমোদন করে।"},
  fr:{q:"Qui dirige la rédaction du plan d’acquisition de l’information et du plan d’appui de la MINUKA ?", o:["Le JMAC, avec validation du MICM","L’état-major particulier du commandant de la force, car l’acquisition est une affaire purement militaire selon le manuel","L’armée de l’État hôte","Chaque chef de patrouille"], e:"Politique 12.6 : le JMAC dirige la rédaction des deux plans et le Mécanisme les valide."}},
 {m:"m4", a:2,
  en:{q:"MINUKA is writing its Support Plan. Which item must it contain?", o:["A complete list of every source’s name, kept in the plan so that all mission staff can check them","National intelligence priorities of each contributor","Acceptable and unacceptable methods, and rights considerations","Only the map of the area of operations"], e:"Policy 12.8: the plan sets boundaries, including acceptable and unacceptable methods, human-rights and legal considerations, security measures and sharing arrangements."},
  bn:{q:"মিনুকা তার সহায়তা পরিকল্পনা লিখছে। এতে কোনটি থাকতেই হবে?", o:["প্রত্যেক উৎসের নামের পূর্ণ তালিকা, পরিকল্পনাতেই রাখা, যাতে মিশনের সব কর্মী তা দেখতে পারেন","প্রতিটি অবদানকারী দেশের জাতীয় গোয়েন্দা অগ্রাধিকার","গ্রহণযোগ্য ও অগ্রহণযোগ্য পদ্ধতি এবং অধিকার বিবেচনা","কেবল অপারেশন এলাকার মানচিত্র"], e:"নীতি ১২.৮: পরিকল্পনা সীমা নির্ধারণ করে, যার মধ্যে গ্রহণযোগ্য ও অগ্রহণযোগ্য পদ্ধতি, মানবাধিকার ও আইনি বিবেচনা, নিরাপত্তা ব্যবস্থা এবং বিনিময় ব্যবস্থা রয়েছে।"},
  fr:{q:"La MINUKA rédige son plan d’appui. Quel élément doit-il contenir ?", o:["La liste complète des noms de toutes les sources, conservée dans le plan pour que tout le personnel puisse les vérifier","Les priorités nationales de renseignement de chaque contributeur","Les méthodes acceptables et inacceptables, et les droits en jeu","La seule carte de la zone d’opérations"], e:"Politique 12.8 : le plan fixe les limites, dont les méthodes acceptables et inacceptables, les considérations juridiques et de droits de l’homme, les mesures de sécurité et les arrangements de partage."}},
 /* ---------- m5 ACQUISITION ---------- */
 {m:"m5", a:2,
  en:{q:"A MINUKA officer wants to give an elder a small cash gift as thanks for repeated information. What is the right answer?", o:["Allowed if the amount is small and recorded, because modest thanks are a normal part of local custom everywhere","Allowed if given to a relative instead","Forbidden: no money or gifts for information; stop and refer","Allowed once the elder asks for it"], e:"HPKI 12.14 bans money or gifts to sources or relatives for information. If the offer has been raised, stop and refer it."},
  bn:{q:"মিনুকার একজন কর্মকর্তা বারবার তথ্য দেওয়ার জন্য ধন্যবাদ হিসেবে একজন প্রবীণকে সামান্য নগদ উপহার দিতে চান। সঠিক উত্তর কী?", o:["পরিমাণ সামান্য ও নথিভুক্ত হলে অনুমোদিত, কারণ সামান্য ধন্যবাদ সর্বত্র স্থানীয় রীতির স্বাভাবিক অংশ","আত্মীয়কে দিলে অনুমোদিত","নিষিদ্ধ: তথ্যের বিনিময়ে অর্থ বা উপহার নয়; থামুন ও জানান","প্রবীণ চাইলে অনুমোদিত"], e:"HPKI ১২.১৪ তথ্যের জন্য উৎস বা আত্মীয়দের অর্থ বা উপহার নিষিদ্ধ করে। প্রস্তাব উঠলে থামুন ও ঊর্ধ্বতনকে জানান।"},
  fr:{q:"Un officier de la MINUKA veut offrir à un ancien une petite somme pour le remercier d’informations répétées. Quelle est la bonne réponse ?", o:["Permis si le montant est faible et consigné, car un modeste remerciement fait partie partout de la coutume locale","Permis si un parent le reçoit","Interdit : ni argent ni cadeau contre information ; arrêter et saisir","Permis si l’ancien le demande"], e:"HPKI 12.14 interdit l’argent ou les cadeaux aux sources ou à leurs proches contre des informations. Si l’offre a été évoquée, arrêtez et saisissez la hiérarchie."}},
 {m:"m5", a:0,
  en:{q:"A boy at a MINUKA camp fence says he can tell patrols where armed men sleep. What should the officer do?", o:["Not use him as a source; refer the safety concern","Ask him to return each week with more detail, since children often move around without attracting any attention","Accept if his parents agree","Accept once if the threat is serious"], e:"HPKI 12.8: children must not be used as sources; they cannot give free and informed consent. Refer any immediate threat and protection concern through mission channels."},
  bn:{q:"মিনুকা ক্যাম্পের বেড়ার কাছে একটি ছেলে বলল, সশস্ত্র লোকেরা কোথায় ঘুমায় তা সে টহল দলকে জানাতে পারে। কর্মকর্তা কী করবেন?", o:["তাকে উৎস হিসেবে ব্যবহার করবেন না; নিরাপত্তা উদ্বেগ জানান","প্রতি সপ্তাহে আরও তথ্য নিয়ে আসতে বলুন, কারণ শিশুরা প্রায়ই কারও নজরে না পড়ে চলাফেরা করে","বাবা-মা রাজি হলে গ্রহণ করুন","হুমকি গুরুতর হলে একবার গ্রহণ করুন"], e:"HPKI ১২.৮: শিশুদের উৎস হিসেবে ব্যবহার করা যাবে না; তারা স্বাধীন ও অবহিত সম্মতি দিতে পারে না। যেকোনো তাৎক্ষণিক হুমকি ও সুরক্ষা উদ্বেগ মিশনের চ্যানেলে জানান।"},
  fr:{q:"Un garçon à la clôture d’un camp de la MINUKA dit pouvoir indiquer où dorment des hommes armés. Que doit faire l’officier ?", o:["Ne pas l’utiliser comme source ; signaler le risque","Lui demander de revenir chaque semaine avec plus de détails, car les enfants circulent souvent sans attirer l’attention","Accepter si ses parents sont d’accord","Accepter une fois si la menace est grave"], e:"HPKI 12.8 : les enfants ne doivent pas servir de sources ; ils ne peuvent donner un consentement libre et éclairé. Signalez toute menace immédiate et tout souci de protection par les voies de la mission."}},
 {m:"m5", a:3,
  en:{q:"A MINUKA analyst suggests an invented online persona to join a closed group discussing attacks. What should the team do?", o:["Proceed if the account never posts, because passive observation does not count as interaction under the Guidelines","Proceed from a personal device","Proceed with the Sector Commander’s approval","Stop and refer: fake accounts are not allowed"], e:"OPKI Guidelines 11.8: operators are not allowed to use fake accounts or hide UN employment online. Material obtained on personal equipment shall not be used for PKI."},
  bn:{q:"মিনুকার একজন বিশ্লেষক হামলা নিয়ে আলোচনা হওয়া একটি বন্ধ গ্রুপে যোগ দিতে বানানো অনলাইন পরিচয়ের পরামর্শ দিলেন। দল কী করবে?", o:["অ্যাকাউন্ট থেকে পোস্ট না করলে এগিয়ে যান, কারণ নির্দেশিকা অনুযায়ী নিষ্ক্রিয় পর্যবেক্ষণ মিথস্ক্রিয়া নয়","ব্যক্তিগত ডিভাইস থেকে এগিয়ে যান","সেক্টর কমান্ডারের অনুমোদনে এগিয়ে যান","থামুন ও জানান: ভুয়া অ্যাকাউন্ট অনুমোদিত নয়"], e:"OPKI নির্দেশিকা ১১.৮: অপারেটররা অনলাইনে ভুয়া অ্যাকাউন্ট ব্যবহার বা জাতিসংঘের চাকরি গোপন করতে পারবেন না। ব্যক্তিগত সরঞ্জামে পাওয়া উপকরণ PKI-তে ব্যবহার করা যাবে না।"},
  fr:{q:"Un analyste de la MINUKA suggère un faux profil en ligne pour rejoindre un groupe fermé qui parle d’attaques. Que doit faire l’équipe ?", o:["Poursuivre si le compte ne publie rien, car l’observation passive n’est pas une interaction selon les Directives","Poursuivre depuis un appareil personnel","Poursuivre avec l’accord du commandant de secteur","Arrêter et saisir : les faux comptes sont interdits"], e:"Directives OPKI 11.8 : les opérateurs ne peuvent utiliser de faux comptes ni cacher leur emploi à l’ONU en ligne. Les éléments obtenus sur un équipement personnel ne doivent pas servir au PKI."}},
 {m:"m5", a:1,
  en:{q:"A MINUKA requirement could be met by tasking an acquisition asset over a Karanan district. What must always be considered first?", o:["Only the technical range of the asset, because legal questions are for headquarters after the task has ended","Host-State permission, the Policy’s limits and human rights","The contributing country’s national priorities","The cost to the unit alone"], e:"PKISR Staff Handbook: tasking must respect Policy boundaries, human rights, international law and do no harm, and Host State permission to operate assets must always be considered."},
  bn:{q:"কারানার একটি জেলায় সংগ্রহ সরঞ্জাম নিযুক্ত করে মিনুকার একটি চাহিদা পূরণ করা যেতে পারে। প্রথমে কী অবশ্যই বিবেচনা করতে হবে?", o:["কেবল সরঞ্জামের কারিগরি পরিসর, কারণ আইনি প্রশ্ন কাজ শেষে সদর দপ্তরের বিষয়","আয়োজক রাষ্ট্রের অনুমতি, নীতির সীমা ও মানবাধিকার","অবদানকারী দেশের জাতীয় অগ্রাধিকার","কেবল ইউনিটের খরচ"], e:"PKISR স্টাফ হ্যান্ডবুক: নিয়োগে নীতির সীমা, মানবাধিকার, আন্তর্জাতিক আইন ও ক্ষতি না করার নীতি মানতে হবে, এবং সরঞ্জাম পরিচালনায় আয়োজক রাষ্ট্রের অনুমতি সবসময় বিবেচ্য।"},
  fr:{q:"Un besoin de la MINUKA pourrait être satisfait en engageant un moyen d’acquisition au-dessus d’un district de Karana. Que faut-il toujours considérer d’abord ?", o:["La seule portée technique du moyen, car les questions juridiques reviennent au QG une fois la tâche finie","L’autorisation de l’État hôte, les limites de la Politique et les droits de l’homme","Les priorités nationales du pays contributeur","Le seul coût pour l’unité"], e:"Manuel PKISR : l’engagement doit respecter les limites de la Politique, les droits de l’homme, le droit international et le principe de ne pas nuire ; l’autorisation de l’État hôte doit toujours être envisagée."}},
 /* ---------- m6 ANALYSIS ---------- */
 {m:"m6", a:1,
  en:{q:"In a MINUKA Analysis of Competing Hypotheses, one piece of evidence fits all three hypotheses. What is its value?", o:["It is decisive, since evidence supported by every hypothesis must be the strongest evidence in the whole matrix","Of little diagnostic value","Proof of the first hypothesis","It must be scored twice"], e:"Evidence consistent with every hypothesis does not help choose among them. ACH looks for evidence that discriminates."},
  bn:{q:"মিনুকার প্রতিযোগী অনুমানের বিশ্লেষণে একটি প্রমাণ তিনটি অনুমানের সঙ্গেই মেলে। এর মূল্য কী?", o:["এটি চূড়ান্ত, কারণ প্রতিটি অনুমান যে প্রমাণকে সমর্থন করে তা অবশ্যই পুরো ম্যাট্রিক্সের সবচেয়ে শক্তিশালী প্রমাণ","পার্থক্য নির্ণয়ে সামান্য মূল্য","প্রথম অনুমানের প্রমাণ","দুবার নম্বর দিতে হবে"], e:"যে প্রমাণ প্রতিটি অনুমানের সঙ্গে মেলে তা বাছাইয়ে সাহায্য করে না। ACH এমন প্রমাণ খোঁজে যা পার্থক্য গড়ে।"},
  fr:{q:"Dans une analyse d’hypothèses concurrentes de la MINUKA, un élément correspond aux trois hypothèses. Quelle est sa valeur ?", o:["Il est décisif, car un élément compatible avec chaque hypothèse est forcément le plus solide de toute la matrice","Faible valeur discriminante","Il prouve la première hypothèse","Il doit être noté deux fois"], e:"Un élément compatible avec chaque hypothèse n’aide pas à choisir. L’ACH recherche ce qui permet de discriminer."}},
 {m:"m6", a:3,
  en:{q:"A contact with an excellent record passes on a market rumour at MINUKA. How should it be graded?", o:["High on everything, because a reliable contact’s reputation transfers fully to anything that contact repeats","Rejected completely as a rumour","Not graded at all","Source and information graded separately"], e:"A good source can pass on a rumour and a poor one can be right. Grading the two separately stops one colouring the other."},
  bn:{q:"মিনুকায় চমৎকার রেকর্ডের একজন যোগাযোগকারী বাজারের একটি গুজব জানালেন। কীভাবে মান নির্ধারণ করবেন?", o:["সবকিছুতে উচ্চ, কারণ নির্ভরযোগ্য যোগাযোগকারীর সুনাম তিনি যা বলেন সবকিছুতে পুরোপুরি বর্তায়","গুজব বলে পুরো বাতিল","কোনো মান নয়","উৎস ও তথ্যের মান আলাদাভাবে"], e:"ভালো উৎসও গুজব জানাতে পারে, দুর্বল উৎসও ঠিক হতে পারে। আলাদা মান নির্ধারণ একটিকে অন্যটি দিয়ে প্রভাবিত হতে দেয় না।"},
  fr:{q:"Un contact aux excellents antécédents transmet une rumeur de marché à la MINUKA. Comment l’évaluer ?", o:["Haut partout, car la réputation d’un contact fiable se transmet entièrement à tout ce qu’il répète","Rejet complet, c’est une rumeur","Aucune évaluation","Source et information évaluées séparément"], e:"Une bonne source peut relayer une rumeur et une source médiocre peut avoir raison. Une évaluation séparée évite que l’une influence l’autre."}},
 {m:"m6", a:0,
  en:{q:"A MINUKA assessment of risk near Oru is based only on interviews with male leaders. What should the analyst do?", o:["Apply a gender lens and state the gap","Publish it unchanged, because community leaders can always speak reliably for every person in their community","Remove all references to women","Drop the assessment altogether"], e:"Men and women may see and face different risks. A gender lens widens the picture, and missing perspectives should be stated as a limit on confidence."},
  bn:{q:"ওরুর কাছে ঝুঁকি নিয়ে মিনুকার একটি মূল্যায়ন কেবল পুরুষ নেতাদের সাক্ষাৎকারের ওপর ভিত্তি করে। বিশ্লেষক কী করবেন?", o:["জেন্ডার দৃষ্টিকোণ প্রয়োগ করে ঘাটতি উল্লেখ করুন","অপরিবর্তিত প্রকাশ করুন, কারণ সমাজের নেতারা সবসময় তাঁদের সমাজের প্রতিটি মানুষের হয়ে নির্ভরযোগ্যভাবে কথা বলতে পারেন","নারীদের সব উল্লেখ মুছে দিন","মূল্যায়নটি পুরো বাদ দিন"], e:"নারী ও পুরুষ ভিন্ন ঝুঁকি দেখতে ও মোকাবিলা করতে পারেন। জেন্ডার দৃষ্টিকোণ চিত্র বিস্তৃত করে, এবং অনুপস্থিত দৃষ্টিভঙ্গি আস্থার সীমা হিসেবে উল্লেখ করা উচিত।"},
  fr:{q:"Une évaluation du risque près d’Oru par la MINUKA repose seulement sur des entretiens avec des dirigeants masculins. Que doit faire l’analyste ?", o:["Appliquer une optique de genre et signaler la lacune","Publier sans changement, car les dirigeants communautaires parlent toujours de façon fiable pour chaque personne de la communauté","Retirer toute mention des femmes","Abandonner totalement l’évaluation"], e:"Femmes et hommes peuvent percevoir et subir des risques différents. L’optique de genre élargit le tableau, et les points de vue manquants doivent être signalés comme limite de la confiance."}},
 {m:"m6", a:2,
  en:{q:"Three MINUKA reports of the same attack all trace back to one radio broadcast. How should collation treat them?", o:["As three independent confirmations, which justifies raising the assessment to the highest level of confidence","As false, because radio cannot be used","As possibly one source; record each origin","As a reason to skip analysis"], e:"Examination and collation keep a record of origin. Three reports may be one source repeated, so they do not add independent weight."},
  bn:{q:"একই হামলা নিয়ে মিনুকার তিনটি প্রতিবেদনের উৎস একটিই রেডিও সম্প্রচার। সমন্বয়ে এগুলোকে কীভাবে দেখবেন?", o:["তিনটি স্বাধীন নিশ্চিতকরণ হিসেবে, যা মূল্যায়নকে সর্বোচ্চ আস্থার স্তরে তোলার যৌক্তিকতা দেয়","মিথ্যা হিসেবে, কারণ রেডিও ব্যবহার করা যায় না","সম্ভবত একটি উৎস হিসেবে; প্রতিটির উৎপত্তি নথিভুক্ত করুন","বিশ্লেষণ বাদ দেওয়ার কারণ হিসেবে"], e:"পরীক্ষা ও সমন্বয়ে উৎপত্তির রেকর্ড রাখা হয়। তিনটি প্রতিবেদন একটিই উৎসের পুনরাবৃত্তি হতে পারে, তাই স্বাধীন গুরুত্ব যোগ করে না।"},
  fr:{q:"Trois rapports de la MINUKA sur la même attaque remontent tous à une seule émission de radio. Comment les traiter à la collation ?", o:["Comme trois confirmations indépendantes, ce qui justifie de porter l’évaluation au plus haut niveau de confiance","Comme faux, car la radio est inutilisable","Comme une source possible ; noter chaque origine","Comme une raison de sauter l’analyse"], e:"L’examen et la collation conservent l’origine. Trois rapports peuvent être une même source répétée et n’ajoutent donc pas de poids indépendant."}},
 /* ---------- m7 PRODUCTS ---------- */
 {m:"m7", a:2,
  en:{q:"A draft MINUKA INTSUM reads: “The KLF will attack Lemu; trucks crossed the bridge.” What is the main fault?", o:["It is too short, as every summary must run to several pages before a decision-maker can properly rely on it","It names a location","Fact and judgement are mixed together","It was written by the U2"], e:"The Handbook requires information and assessment to be kept clearly distinct, so the reader can see what was observed and what is judged."},
  bn:{q:"মিনুকার একটি খসড়া INTSUM-এ লেখা: “KLF লেমুতে হামলা করবে; ট্রাক সেতু পার হয়েছে।” প্রধান ত্রুটি কী?", o:["এটি খুব ছোট, কারণ সিদ্ধান্তগ্রহীতা ভরসা করার আগে প্রতিটি সারসংক্ষেপ কয়েক পৃষ্ঠা হওয়া আবশ্যক","এতে স্থানের নাম আছে","তথ্য ও বিচার মিশে গেছে","এটি U2 লিখেছে"], e:"হ্যান্ডবুক তথ্য ও মূল্যায়ন স্পষ্টভাবে আলাদা রাখতে বলে, যাতে পাঠক বোঝেন কী দেখা গেছে এবং কী অনুমান।"},
  fr:{q:"Un projet d’INTSUM de la MINUKA indique : « Le KLF attaquera Lemu ; des camions ont franchi le pont. » Quel est le principal défaut ?", o:["Il est trop court, car toute synthèse doit faire plusieurs pages avant qu’un décideur puisse s’y fier","Il nomme un lieu","Faits et jugement sont mêlés","Il a été rédigé par l’U2"], e:"Le manuel exige de bien distinguer information et évaluation, afin que le lecteur voie ce qui est observé et ce qui est jugé."}},
 {m:"m7", a:0,
  en:{q:"A MINUKA commander must decide within hours on a convoy and needs a structured view of the threat. Which product fits best?", o:["A Short Estimate (SPIE)","A full estimate (PIE) that takes several weeks, because a longer document always leads to a better decision","A thematic report on the region’s history","A yearly review"], e:"The SPIE is the shortened estimate for when time does not allow a full PIE."},
  bn:{q:"মিনুকার একজন কমান্ডারকে কয়েক ঘণ্টার মধ্যে একটি কনভয় নিয়ে সিদ্ধান্ত নিতে হবে এবং হুমকির কাঠামোবদ্ধ চিত্র দরকার। কোন পণ্য সবচেয়ে উপযুক্ত?", o:["সংক্ষিপ্ত প্রাক্কলন (SPIE)","কয়েক সপ্তাহ লাগা পূর্ণ প্রাক্কলন (PIE), কারণ দীর্ঘতর দলিল সবসময় ভালো সিদ্ধান্তে নিয়ে যায়","অঞ্চলের ইতিহাস নিয়ে থিম্যাটিক প্রতিবেদন","বার্ষিক পর্যালোচনা"], e:"পূর্ণ PIE-এর সময় না থাকলে সংক্ষিপ্ত প্রাক্কলন SPIE ব্যবহৃত হয়।"},
  fr:{q:"Un commandant de la MINUKA doit décider d’un convoi en quelques heures et a besoin d’une vue structurée de la menace. Quel produit convient le mieux ?", o:["Une estimation abrégée (SPIE)","Une estimation complète (PIE) de plusieurs semaines, car un document plus long mène toujours à une meilleure décision","Un rapport thématique sur l’histoire de la région","Un bilan annuel"], e:"La SPIE est l’estimation abrégée, quand le temps manque pour une PIE complète."}},
 {m:"m7", a:1,
  en:{q:"At 1400 a MINUKA analyst learns of a development that should not wait for tomorrow’s summary. Which product should be used?", o:["Tomorrow’s INTSUM, since all new information must wait for the regular cycle whatever its urgency may be","An INTREP","A thematic report","No product; tell a friend at the JOC"], e:"The INTREP reports a specific development that should not wait; the INTSUM is the periodic summary."},
  bn:{q:"দুপুর ২টায় মিনুকার একজন বিশ্লেষক এমন একটি ঘটনা জানলেন যা আগামীকালের সারসংক্ষেপের জন্য অপেক্ষা করতে পারে না। কোন পণ্য ব্যবহার করবেন?", o:["আগামীকালের INTSUM, কারণ যত জরুরিই হোক, সব নতুন তথ্যকে নিয়মিত চক্রের জন্য অপেক্ষা করতে হয়","একটি INTREP","থিম্যাটিক প্রতিবেদন","কোনো পণ্য নয়; JOC-এর বন্ধুকে বলুন"], e:"INTREP এমন নির্দিষ্ট ঘটনা জানায় যা অপেক্ষা করতে পারে না; INTSUM হলো নিয়মিত সারসংক্ষেপ।"},
  fr:{q:"À 14 h, un analyste de la MINUKA apprend un fait qui ne peut attendre la synthèse de demain. Quel produit utiliser ?", o:["L’INTSUM de demain, car toute information nouvelle doit attendre le cycle régulier quelle que soit son urgence","Un INTREP","Un rapport thématique","Aucun ; prévenir un ami au JOC"], e:"L’INTREP signale un fait précis qui ne peut attendre ; l’INTSUM est la synthèse périodique."}},
 {m:"m7", a:3,
  en:{q:"MINUKA’s Head of Mission asks at short notice: “Will they attack the camp this week?” The evidence is incomplete. What is the best briefing?", o:["Delay any answer until the evidence is complete, because a judgement should never be given while gaps remain","Say simply yes, to sound confident","Read out all raw reports","Give a judgement, its confidence and the gaps, on time"], e:"PKI serves decisions. A timely judgement that shows its confidence and gaps is more useful than a late certainty or a pile of raw reports."},
  bn:{q:"মিনুকার মিশন প্রধান হঠাৎ জিজ্ঞাসা করলেন: “এই সপ্তাহে তারা কি ক্যাম্পে হামলা করবে?” প্রমাণ অসম্পূর্ণ। সেরা ব্রিফিং কী?", o:["প্রমাণ সম্পূর্ণ না হওয়া পর্যন্ত উত্তর দেরি করুন, কারণ ঘাটতি থাকলে কখনোই বিচার দেওয়া উচিত নয়","আত্মবিশ্বাসী শোনাতে শুধু হ্যাঁ বলুন","সব কাঁচা প্রতিবেদন পড়ে শোনান","সময়মতো বিচার, আস্থা ও ঘাটতি জানান"], e:"PKI সিদ্ধান্তের জন্য। আস্থা ও ঘাটতি দেখানো সময়মতো বিচার দেরিতে পাওয়া নিশ্চয়তা বা কাঁচা প্রতিবেদনের স্তূপের চেয়ে বেশি কাজের।"},
  fr:{q:"Le chef de la MINUKA demande à bref délai : « Attaqueront-ils le camp cette semaine ? » Les éléments sont incomplets. Quel est le meilleur exposé ?", o:["Retarder toute réponse jusqu’à ce que les éléments soient complets, car on ne juge jamais quand il reste des lacunes","Dire simplement oui, pour paraître sûr","Lire tous les rapports bruts","Un jugement, sa confiance et les lacunes, à temps"], e:"Le PKI sert les décisions. Un jugement opportun qui montre sa confiance et ses lacunes vaut mieux qu’une certitude tardive ou une pile de rapports bruts."}},
 /* ---------- m8 HANDLING ---------- */
 {m:"m8", a:3,
  en:{q:"A MINUKA section marks all of its products Strictly Confidential by habit. What does the Policy say?", o:["This is correct practice, because the highest available marking should always be applied to protect every product","Only UNHQ may mark products","Markings are optional decoration","Sharing in the mission is default; such marks are exceptional"], e:"Policy 11.2.1: the default is sharing within the mission; Confidential or Strictly Confidential apply only on an exceptional basis."},
  bn:{q:"মিনুকার একটি শাখা অভ্যাসবশত তার সব পণ্যকে Strictly Confidential চিহ্নিত করে। নীতি কী বলে?", o:["এটি সঠিক চর্চা, কারণ প্রতিটি পণ্য রক্ষায় সর্বদা সর্বোচ্চ উপলব্ধ চিহ্ন প্রয়োগ করা উচিত","কেবল UNHQ চিহ্নিত করতে পারে","চিহ্ন ঐচ্ছিক সাজসজ্জা","মিশনের ভেতরে বিনিময়ই স্বাভাবিক; এই চিহ্ন ব্যতিক্রম"], e:"নীতি ১১.২.১: মিশনের ভেতরে বিনিময়ই স্বাভাবিক; Confidential বা Strictly Confidential কেবল ব্যতিক্রম হিসেবে।"},
  fr:{q:"Une section de la MINUKA marque tous ses produits Strictly Confidential par habitude. Que dit la Politique ?", o:["C’est une pratique correcte, car le marquage le plus élevé doit toujours s’appliquer pour protéger chaque produit","Seul le Siège peut marquer","Les marquages sont facultatifs","Le partage interne est la règle ; ces marques sont l’exception"], e:"Politique 11.2.1 : le partage au sein de la mission est la règle ; Confidential ou Strictly Confidential ne s’appliquent qu’à titre exceptionnel."}},
 {m:"m8", a:1,
  en:{q:"Karana’s army urgently asks MINUKA for a threat product before an operation tonight. What applies?", o:["Skip the assessments, because the Sharing Guidelines waive every step whenever a request is truly urgent","Urgency waives nothing: assessments and HRDDP still apply","Any officer may decide at the gate","Send it unsanitized to save time"], e:"Sharing Guidelines 8.1.7: urgency does not waive the steps. Entity and Sharing Risk Assessments, HRDDP, written conditions and sanitization remain."},
  bn:{q:"আজ রাতের অভিযানের আগে কারানার সেনাবাহিনী জরুরিভাবে মিনুকার কাছে একটি হুমকি পণ্য চাইল। কী প্রযোজ্য?", o:["মূল্যায়ন বাদ দিন, কারণ অনুরোধ সত্যিই জরুরি হলে বিনিময় নির্দেশিকা প্রতিটি ধাপ মওকুফ করে","জরুরি অবস্থা কিছু মওকুফ করে না: মূল্যায়ন ও HRDDP প্রযোজ্য","যেকোনো কর্মকর্তা ফটকেই সিদ্ধান্ত নিতে পারেন","সময় বাঁচাতে অপরিশোধিত অবস্থায় পাঠান"], e:"বিনিময় নির্দেশিকা ৮.১.৭: জরুরি অবস্থা ধাপগুলো মওকুফ করে না। সত্তা ও বিনিময় ঝুঁকি মূল্যায়ন, HRDDP, লিখিত শর্ত ও স্যানিটাইজেশন বহাল থাকে।"},
  fr:{q:"L’armée de Karana demande d’urgence à la MINUKA un produit sur la menace avant une opération ce soir. Que s’applique-t-il ?", o:["Sauter les évaluations, car les Directives dispensent de chaque étape lorsqu’une demande est vraiment urgente","L’urgence ne dispense de rien : évaluations et HRDDP s’appliquent","Tout officier décide à l’entrée","Envoyer sans assainir pour gagner du temps"], e:"Directives sur le partage 8.1.7 : l’urgence ne dispense pas des étapes. Évaluations de l’entité et du risque, HRDDP, conditions écrites et assainissement demeurent."}},
 {m:"m8", a:0,
  en:{q:"A partner offers MINUKA a report drawn from a prisoner, and there is a real risk that he was tortured. What should the mission do?", o:["Neither accept nor solicit it; tell the human rights component","Accept it if the threat is imminent, because protecting civilians outweighs any concern about how it was obtained","Accept but remove the prisoner’s name","Ask the partner to rewrite the report"], e:"Sharing Guidelines 9.9: where there is a real risk, missions shall neither accept nor solicit it, and the human rights component is told immediately."},
  bn:{q:"একজন অংশীদার মিনুকাকে একজন বন্দির কাছ থেকে পাওয়া প্রতিবেদন দিতে চাইল, এবং তাঁকে নির্যাতনের প্রকৃত ঝুঁকি রয়েছে। মিশন কী করবে?", o:["গ্রহণও নয়, চাওয়াও নয়; মানবাধিকার অংশকে জানান","হুমকি আসন্ন হলে গ্রহণ করুন, কারণ বেসামরিক সুরক্ষা এটি কীভাবে পাওয়া গেছে সেই উদ্বেগের চেয়ে বড়","গ্রহণ করে বন্দির নাম মুছে দিন","অংশীদারকে প্রতিবেদন আবার লিখতে বলুন"], e:"বিনিময় নির্দেশিকা ৯.৯: প্রকৃত ঝুঁকি থাকলে মিশন তা গ্রহণ বা চাইবে না, এবং মানবাধিকার অংশকে সঙ্গে সঙ্গে জানানো হবে।"},
  fr:{q:"Un partenaire propose à la MINUKA un rapport issu d’un prisonnier, avec un risque réel de torture. Que doit faire la mission ?", o:["Ni l’accepter ni le solliciter ; informer les droits de l’homme","L’accepter si la menace est imminente, car protéger les civils l’emporte sur tout souci quant à son obtention","L’accepter en retirant le nom du prisonnier","Demander au partenaire de le réécrire"], e:"Directives 9.9 : en cas de risque réel, les missions ne doivent ni l’accepter ni le solliciter, et la composante droits de l’homme est aussitôt informée."}},
 {m:"m8", a:2,
  en:{q:"MINUKA’s only basis for moving a battalion is one intelligence report received from a partner. What is the rule?", o:["Act at once, because a report from a trusted partner may stand on its own for any mission decision","Act only if the partner signs it","It must never be the sole determining source","Ignore all partner reports"], e:"Sharing Guidelines: received intelligence shall never be the sole determining source for any mission action or decision."},
  bn:{q:"একটি ব্যাটালিয়ন সরানোর জন্য মিনুকার একমাত্র ভিত্তি অংশীদারের কাছ থেকে পাওয়া একটি গোয়েন্দা প্রতিবেদন। নিয়ম কী?", o:["সঙ্গে সঙ্গে ব্যবস্থা নিন, কারণ বিশ্বস্ত অংশীদারের প্রতিবেদন যেকোনো মিশন সিদ্ধান্তে একাই যথেষ্ট হতে পারে","অংশীদার স্বাক্ষর করলেই ব্যবস্থা নিন","এটি কখনো একমাত্র নির্ধারক উৎস হবে না","অংশীদারের সব প্রতিবেদন উপেক্ষা করুন"], e:"বিনিময় নির্দেশিকা: প্রাপ্ত গোয়েন্দা তথ্য কোনো মিশন পদক্ষেপ বা সিদ্ধান্তের একমাত্র নির্ধারক উৎস হবে না।"},
  fr:{q:"La seule base de la MINUKA pour déplacer un bataillon est un rapport reçu d’un partenaire. Quelle est la règle ?", o:["Agir aussitôt, car le rapport d’un partenaire de confiance peut suffire seul pour toute décision de la mission","Agir seulement si le partenaire signe","Il ne doit jamais être la seule source déterminante","Ignorer tous les rapports de partenaires"], e:"Directives sur le partage : le renseignement reçu ne doit jamais être la seule source déterminante d’une action ou décision de la mission."}},
 /* ---------- m9 PROTECTION ---------- */
 {m:"m9", a:0,
  en:{q:"A MINUKA product marked for limited circulation shows a threat to UN staff in Lemu. Where must this go?", o:["To the senior-most UNDSS representative, on time","To no one outside the section, because the marking takes priority over any safety concern for personnel in the area","Only into next month’s summary","Only to the troop-contributing country"], e:"Policy 11.3.2: anything affecting the safety of UN personnel must go to the senior-most UNDSS representative in a timely fashion."},
  bn:{q:"সীমিত প্রচারের জন্য চিহ্নিত মিনুকার একটি পণ্যে লেমুতে জাতিসংঘ কর্মীদের ওপর হুমকি দেখা যাচ্ছে। এটি কোথায় যাবে?", o:["সর্বোচ্চ UNDSS প্রতিনিধির কাছে, সময়মতো","শাখার বাইরে কারও কাছে নয়, কারণ এলাকার কর্মীদের নিরাপত্তা উদ্বেগের চেয়ে চিহ্নের অগ্রাধিকার বেশি","কেবল আগামী মাসের সারসংক্ষেপে","কেবল সৈন্য প্রদানকারী দেশের কাছে"], e:"নীতি ১১.৩.২: জাতিসংঘ কর্মীদের নিরাপত্তা প্রভাবিত করে এমন যেকোনো কিছু সময়মতো সর্বোচ্চ UNDSS প্রতিনিধির কাছে যেতে হবে।"},
  fr:{q:"Un produit de la MINUKA à diffusion restreinte révèle une menace contre le personnel de l’ONU à Lemu. Où doit-il aller ?", o:["Au plus haut représentant de l’UNDSS, à temps","À personne hors de la section, car le marquage prime sur tout souci de sécurité du personnel dans la zone","Seulement dans la synthèse du mois suivant","Seulement au pays fournisseur de contingents"], e:"Politique 11.3.2 : tout ce qui touche à la sécurité du personnel doit être transmis en temps utile au plus haut représentant de l’UNDSS."}},
 {m:"m9", a:2,
  en:{q:"While analysing patrol reports, a MINUKA S2 finds signs of conflict-related sexual violence. What should happen?", o:["Keep it inside the cycle, since it was not part of the question asked and reporting it could endanger the assessment","Investigate alone first","Report it through the appropriate channels","Wait for a formal requirement"], e:"The Military PKI Handbook: violations, including trafficking, conflict-related sexual violence and grave violations against children, have mandatory reporting requirements."},
  bn:{q:"টহল প্রতিবেদন বিশ্লেষণের সময় মিনুকার একজন S2 সংঘাত-সম্পর্কিত যৌন সহিংসতার লক্ষণ পেলেন। কী হওয়া উচিত?", o:["চক্রের ভেতরেই রাখুন, কারণ এটি জিজ্ঞাসিত প্রশ্নের অংশ ছিল না এবং জানালে মূল্যায়ন বিপন্ন হতে পারে","আগে একাই তদন্ত করুন","যথাযথ চ্যানেলে প্রতিবেদন করুন","আনুষ্ঠানিক চাহিদার অপেক্ষা করুন"], e:"সামরিক PKI হ্যান্ডবুক: পাচার, সংঘাত-সম্পর্কিত যৌন সহিংসতা ও শিশুদের বিরুদ্ধে গুরুতর লঙ্ঘনসহ লঙ্ঘনগুলোর বাধ্যতামূলক প্রতিবেদনের নিয়ম আছে।"},
  fr:{q:"En analysant des rapports de patrouille, un S2 de la MINUKA trouve des signes de violences sexuelles liées au conflit. Que faire ?", o:["Les garder dans le cycle, car ce n’était pas la question posée et les signaler pourrait compromettre l’évaluation","Enquêter d’abord seul","Signaler par les voies appropriées","Attendre un besoin formel"], e:"Manuel militaire : les violations, dont la traite, les violences sexuelles liées aux conflits et les violations graves contre les enfants, sont soumises à une obligation de signalement."}},
 {m:"m9", a:3,
  en:{q:"A Karanan radio station spreads a false story about MINUKA. Staff want it shut down because it is false. What does the Information Integrity Policy suggest?", o:["Press for closure, because falsity alone is always enough to justify limiting speech in a mission area","Reply with an invented story","Ignore all rumours","Falsity alone is not enough; favour verified information"], e:"Falsity alone is not grounds to limit expression, and speech restrictions are only rarely right. The default is free and open exchange of information."},
  bn:{q:"কারানার একটি রেডিও মিনুকা নিয়ে মিথ্যা খবর ছড়াচ্ছে। কর্মীরা মিথ্যা বলে এটি বন্ধ করতে চান। তথ্য অখণ্ডতা নীতি কী বলে?", o:["বন্ধের জন্য চাপ দিন, কারণ মিশন এলাকায় মিথ্যা হওয়াই বক্তব্য সীমিত করার জন্য সবসময় যথেষ্ট","বানানো গল্প দিয়ে জবাব দিন","সব গুজব উপেক্ষা করুন","মিথ্যা হওয়াই যথেষ্ট নয়; যাচাইকৃত তথ্য দিন"], e:"কেবল মিথ্যা হওয়া মতপ্রকাশ সীমিত করার ভিত্তি নয়, এবং বক্তব্যে নিষেধাজ্ঞা কদাচিৎ সঠিক। স্বাভাবিক নিয়ম হলো তথ্যের অবাধ ও উন্মুক্ত বিনিময়।"},
  fr:{q:"Une radio de Karana diffuse une fausse histoire sur la MINUKA. Le personnel veut la faire fermer parce que c’est faux. Que suggère la Politique sur l’intégrité de l’information ?", o:["Faire pression pour la fermeture, car la fausseté suffit toujours à justifier de limiter la parole dans la zone de mission","Répondre par une histoire inventée","Ignorer toutes les rumeurs","La fausseté ne suffit pas ; privilégier l’information vérifiée"], e:"La seule fausseté ne justifie pas de limiter l’expression, et les restrictions ne sont que rarement la bonne réponse. La règle est l’échange libre et ouvert."}},
 {m:"m9", a:1,
  en:{q:"Hate speech in Karana begins to threaten a displaced community protected by MINUKA. How does it reach PKI work?", o:["It cannot, because information integrity and peacekeeping-intelligence are completely separate worlds with no link","Through the requirements process","Only through a press release","By private request to a friend"], e:"Information Integrity Policy para 38: where such content risks safety or protection of civilians, it goes into the requirements process, triggering acquisition by PKI entities."},
  bn:{q:"কারানায় বিদ্বেষমূলক বক্তব্য মিনুকার সুরক্ষায় থাকা একটি বাস্তুচ্যুত জনগোষ্ঠীকে হুমকিতে ফেলছে। এটি PKI কাজে কীভাবে পৌঁছায়?", o:["পৌঁছাতে পারে না, কারণ তথ্য অখণ্ডতা ও শান্তিরক্ষা-গোয়েন্দা তথ্য সম্পূর্ণ আলাদা জগৎ, কোনো সংযোগ নেই","চাহিদা প্রক্রিয়ার মাধ্যমে","কেবল প্রেস বিজ্ঞপ্তির মাধ্যমে","বন্ধুর কাছে ব্যক্তিগত অনুরোধে"], e:"তথ্য অখণ্ডতা নীতির অনুচ্ছেদ ৩৮: এ ধরনের বিষয়বস্তু নিরাপত্তা বা বেসামরিক সুরক্ষায় ঝুঁকি তৈরি করলে তা চাহিদা প্রক্রিয়ায় যায় এবং PKI সত্তার সংগ্রহ শুরু করে।"},
  fr:{q:"Des discours de haine à Karana menacent une communauté déplacée protégée par la MINUKA. Comment cela rejoint-il le travail PKI ?", o:["C’est impossible, car l’intégrité de l’information et le renseignement sont deux mondes séparés sans aucun lien","Par le processus des besoins","Seulement par un communiqué","Par demande privée à un ami"], e:"Politique sur l’intégrité de l’information, par. 38 : si ces contenus menacent la sécurité ou la protection des civils, ils entrent dans le processus des besoins et déclenchent l’acquisition par les entités PKI."}},
 /* ---------- m10 POLICING ---------- */
 {m:"m10", a:1,
  en:{q:"A MINUKA UNPOL trainer must separate three terms. Which pairing is right?", o:["Criminal intelligence is about crimes, while crime analysis is about offenders, and crime intelligence replaces both of them","Criminal intelligence: offenders; crime analysis: crimes; crime intelligence: both","All three mean the same","Only crime analysis is lawful"], e:"ILP Manual p.7: criminal intelligence concerns offenders, crime analysis concerns crimes, and crime intelligence fuses both."},
  bn:{q:"মিনুকার একজন UNPOL প্রশিক্ষককে তিনটি পরিভাষা আলাদা করতে হবে। কোন জোড়া সঠিক?", o:["অপরাধী গোয়েন্দা তথ্য অপরাধ নিয়ে, অপরাধ বিশ্লেষণ অপরাধী নিয়ে, আর অপরাধ গোয়েন্দা তথ্য উভয়ের স্থান নেয়","অপরাধী গোয়েন্দা তথ্য: অপরাধী; অপরাধ বিশ্লেষণ: অপরাধ; অপরাধ গোয়েন্দা তথ্য: উভয়","তিনটির অর্থ একই","কেবল অপরাধ বিশ্লেষণ বৈধ"], e:"ILP ম্যানুয়াল পৃ. ৭: অপরাধী গোয়েন্দা তথ্য অপরাধী নিয়ে, অপরাধ বিশ্লেষণ অপরাধ নিয়ে, এবং অপরাধ গোয়েন্দা তথ্য দুটিকে একত্র করে।"},
  fr:{q:"Un formateur d’UNPOL de la MINUKA doit distinguer trois termes. Quelle répartition est juste ?", o:["Le renseignement criminel porte sur les crimes, l’analyse criminelle sur les auteurs, et le renseignement sur la criminalité remplace les deux","Renseignement criminel : auteurs ; analyse : crimes ; renseignement sur la criminalité : les deux","Les trois sont synonymes","Seule l’analyse criminelle est licite"], e:"Manuel ILP p. 7 : le renseignement criminel concerne les auteurs, l’analyse criminelle les crimes, et le renseignement sur la criminalité fusionne les deux."}},
 {m:"m10", a:3,
  en:{q:"MINUKA’s police component wants its crime priorities reflected in the mission’s PKI direction. Which link does the ILP Manual describe?", o:["A private line from each officer to the Head of Mission, which replaces all coordination across the mission","Direct tasking of the Host State’s police","A monthly press conference","The Tasking and Co-ordination Group feeding the MICM"], e:"ILP Manual p.31: the Tasking and Co-ordination Group feeds requirements to the MICM and meets quarterly."},
  bn:{q:"মিনুকার পুলিশ অংশ চায় তাদের অপরাধ অগ্রাধিকার মিশনের PKI নির্দেশনায় প্রতিফলিত হোক। ILP ম্যানুয়াল কোন সংযোগের কথা বলে?", o:["প্রত্যেক কর্মকর্তা থেকে মিশন প্রধানের কাছে ব্যক্তিগত লাইন, যা মিশনজুড়ে সব সমন্বয়ের স্থান নেয়","আয়োজক রাষ্ট্রের পুলিশকে সরাসরি দায়িত্ব দেওয়া","মাসিক সংবাদ সম্মেলন","টাস্কিং ও সমন্বয় গ্রুপ থেকে MICM-এ"], e:"ILP ম্যানুয়াল পৃ. ৩১: টাস্কিং ও সমন্বয় গ্রুপ MICM-কে চাহিদা জানায় এবং ত্রৈমাসিক বৈঠক করে।"},
  fr:{q:"La composante police de la MINUKA veut voir ses priorités criminelles reflétées dans la direction PKI. Quel lien le manuel ILP décrit-il ?", o:["Une ligne privée de chaque officier au chef de mission, qui remplace toute la coordination dans la mission","Le pilotage direct de la police de l’État hôte","Une conférence de presse mensuelle","Le Groupe de tâches et de coordination alimentant le MICM"], e:"Manuel ILP p. 31 : le Groupe de tâches et de coordination transmet les besoins au MICM et se réunit chaque trimestre."}},
 {m:"m10", a:0,
  en:{q:"A Karanan prosecutor wants to use a MINUKA assessment as proof in court. What is the sound starting point?", o:["Intelligence is not evidence; competent authorities decide","Any UN assessment is automatically admissible, since the Organization’s reports carry full proof in all national courts","UNPOL rules on admissibility","The mission’s lawyer decides guilt"], e:"Assessments are not proof of facts. As the TPKI Guidelines note on evidential value, the final word on evidence rests with competent authorities, and sharing rules still apply."},
  bn:{q:"কারানার একজন প্রসিকিউটর মিনুকার একটি মূল্যায়ন আদালতে প্রমাণ হিসেবে ব্যবহার করতে চান। সঠিক সূচনা বিন্দু কী?", o:["গোয়েন্দা তথ্য প্রমাণ নয়; উপযুক্ত কর্তৃপক্ষ সিদ্ধান্ত নেয়","জাতিসংঘের যেকোনো মূল্যায়ন স্বয়ংক্রিয়ভাবে গ্রহণযোগ্য, কারণ সংস্থার প্রতিবেদন সব জাতীয় আদালতে পূর্ণ প্রমাণ","গ্রহণযোগ্যতা UNPOL ঠিক করে","মিশনের আইনজীবী দোষ নির্ধারণ করেন"], e:"মূল্যায়ন ঘটনার প্রমাণ নয়। TPKI নির্দেশিকা প্রমাণমূল্য প্রসঙ্গে বলে, প্রমাণ বিষয়ে চূড়ান্ত কথা উপযুক্ত কর্তৃপক্ষের, এবং বিনিময়ের নিয়মও প্রযোজ্য।"},
  fr:{q:"Un procureur de Karana veut utiliser une évaluation de la MINUKA comme preuve au tribunal. Quel est le bon point de départ ?", o:["Le renseignement n’est pas une preuve ; l’autorité compétente décide","Toute évaluation de l’ONU est recevable d’office, car ses rapports font pleine preuve devant tous les tribunaux nationaux","UNPOL statue sur la recevabilité","Le juriste de la mission décide de la culpabilité"], e:"Une évaluation ne prouve pas les faits. Comme le notent les Directives TPKI sur la valeur probante, le dernier mot revient aux autorités compétentes, et les règles de partage demeurent."}},
 {m:"m10", a:2,
  en:{q:"Karana’s police ask MINUKA UNPOL, which is mentoring them, for its file of suspects. What applies?", o:["Hand it over, because a capacity-building relationship removes every human-rights check on sharing","Hand over names but not dates","HRDDP and the sharing rules apply","UNPOL may never speak with host police"], e:"ILP Manual p.34: HRDDP applies to sharing with non-UN security forces. Capacity-building does not remove the sharing steps."},
  bn:{q:"মিনুকার UNPOL যাদের মেন্টরিং করছে সেই কারানার পুলিশ সন্দেহভাজনদের ফাইল চাইল। কী প্রযোজ্য?", o:["হস্তান্তর করুন, কারণ সক্ষমতা উন্নয়নের সম্পর্ক বিনিময়ের সব মানবাধিকার যাচাই তুলে দেয়","নাম দিন, তারিখ নয়","HRDDP ও বিনিময়ের নিয়ম প্রযোজ্য","UNPOL আয়োজক পুলিশের সঙ্গে কথাই বলতে পারে না"], e:"ILP ম্যানুয়াল পৃ. ৩৪: অ-জাতিসংঘ নিরাপত্তা বাহিনীর সঙ্গে বিনিময়ে HRDDP প্রযোজ্য। সক্ষমতা উন্নয়ন বিনিময়ের ধাপগুলো তুলে দেয় না।"},
  fr:{q:"La police de Karana, encadrée par UNPOL de la MINUKA, demande son dossier de suspects. Que s’applique-t-il ?", o:["Le remettre, car une relation de renforcement des capacités supprime tout contrôle des droits de l’homme sur le partage","Remettre les noms mais pas les dates","La HRDDP et les règles de partage s’appliquent","UNPOL ne peut jamais parler à la police hôte"], e:"Manuel ILP p. 34 : la HRDDP s’applique au partage avec des forces de sécurité non onusiennes. Le renforcement des capacités ne supprime pas ces étapes."}},
 /* ---------- m11 NEW-THREATS ---------- */
 {m:"m11", a:2,
  en:{q:"A MINUKA trainer is teaching the 13 December 2025 Kadugli attack. Which statement is sound?", o:["Name the group responsible, because national statements made soon after an attack settle the question of who did it","Say no peacekeepers were harmed","Six Bangladeshi peacekeepers killed, at least eight injured; no attribution","Say the UN has published final findings"], e:"Sources differ on the injured (eight or nine). Sudan’s government and the RSF traded claims and no investigation findings were found, so the course does not attribute the attack."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক ১৩ ডিসেম্বর ২০২৫ সালের কাদুগলি হামলা পড়াচ্ছেন। কোন বক্তব্য যথাযথ?", o:["দায়ী গোষ্ঠীর নাম বলুন, কারণ হামলার পরপর দেওয়া জাতীয় বিবৃতিই ঠিক করে দেয় কে করেছে","বলুন কোনো শান্তিরক্ষীর ক্ষতি হয়নি","ছয় বাংলাদেশি শান্তিরক্ষী নিহত, অন্তত আটজন আহত; দায় আরোপ নয়","বলুন জাতিসংঘ চূড়ান্ত ফলাফল প্রকাশ করেছে"], e:"আহতের সংখ্যায় উৎসভেদে পার্থক্য আছে (আট বা নয়)। সুদান সরকার ও RSF পরস্পরকে দায়ী করেছে এবং তদন্তের ফলাফল পাওয়া যায়নি, তাই কোর্সে দায় আরোপ করা হয় না।"},
  fr:{q:"Un formateur de la MINUKA enseigne l’attaque de Kadugli du 13 décembre 2025. Quelle affirmation est solide ?", o:["Nommer le groupe responsable, car les déclarations nationales faites peu après une attaque tranchent la question de son auteur","Dire qu’aucun casque bleu n’a été touché","Six Casques bleus bangladais tués, au moins huit blessés ; pas d’attribution","Dire que l’ONU a publié des conclusions définitives"], e:"Les sources divergent sur les blessés (huit ou neuf). Le gouvernement soudanais et les FSR se sont renvoyé les accusations et aucune conclusion d’enquête n’a été trouvée : le cours n’attribue pas l’attaque."}},
 {m:"m11", a:0,
  en:{q:"Technical findings from fragments near Lemu could help Karana’s army strike a group’s leaders. What does the TPKI rule say?", o:["No kinetic targeting, unless the mandate says so to reduce civilian harm","Allowed whenever the targeted group has already attacked the mission, because self-defence overrides the Guidelines","Allowed if the U2 agrees","Allowed if the results are sanitized"], e:"TPKI Guidelines para 10: the UN does not use TPKI to support kinetic targeting of individuals or groups, unless explicitly in the mandate and aimed at mitigating civilian harm."},
  bn:{q:"লেমুর কাছে পাওয়া টুকরোর কারিগরি ফলাফল কারানার সেনাবাহিনীকে একটি গোষ্ঠীর নেতাদের ওপর আঘাত হানতে সাহায্য করতে পারে। TPKI নিয়ম কী বলে?", o:["কাইনেটিক টার্গেটিং নয়, যদি না ম্যান্ডেটে বেসামরিক ক্ষতি কমাতে তা বলা থাকে","লক্ষ্যবস্তু গোষ্ঠী আগেই মিশনে হামলা করলে অনুমোদিত, কারণ আত্মরক্ষা নির্দেশিকার ঊর্ধ্বে","U2 রাজি হলে অনুমোদিত","ফলাফল স্যানিটাইজ করলে অনুমোদিত"], e:"TPKI নির্দেশিকা অনু. ১০: জাতিসংঘ ব্যক্তি বা গোষ্ঠীর বিরুদ্ধে কাইনেটিক টার্গেটিং সমর্থনে TPKI ব্যবহার করে না, যদি না তা ম্যান্ডেটে স্পষ্টভাবে থাকে এবং বেসামরিক ক্ষতি কমানোর লক্ষ্যে হয়।"},
  fr:{q:"Des résultats techniques sur des fragments près de Lemu pourraient aider l’armée de Karana à frapper les chefs d’un groupe. Que dit la règle TPKI ?", o:["Pas de ciblage cinétique, sauf mandat explicite pour réduire les dommages aux civils","Permis dès lors que le groupe visé a déjà attaqué la mission, car la légitime défense prime sur les Directives","Permis si l’U2 est d’accord","Permis si les résultats sont assainis"], e:"Directives TPKI, par. 10 : l’ONU n’utilise pas le TPKI à l’appui du ciblage cinétique de personnes ou de groupes, sauf mention explicite au mandat et but d’atténuer les dommages aux civils."}},
 {m:"m11", a:3,
  en:{q:"A MINUKA patrol finds a suspicious object by the road and an officer wants to bring it back for the analysts. What is correct?", o:["Bring it back quickly, because analysts need the object in hand before any other team becomes involved","Photograph it close up, then move it","Ask a local volunteer to handle it","Keep clear; explosive ordnance disposal teams go first"], e:"TPKI Guidelines: technical acquisition is for experts, with EOD teams first where explosives are suspected."},
  bn:{q:"মিনুকার একটি টহল দল রাস্তার পাশে সন্দেহজনক বস্তু পেল এবং একজন কর্মকর্তা সেটি বিশ্লেষকদের জন্য নিয়ে আসতে চান। সঠিক কী?", o:["দ্রুত নিয়ে আসুন, কারণ অন্য কোনো দল যুক্ত হওয়ার আগে বিশ্লেষকদের হাতে বস্তুটি থাকা দরকার","কাছ থেকে ছবি তুলে সরিয়ে নিন","স্থানীয় স্বেচ্ছাসেবককে ধরতে বলুন","দূরে থাকুন; আগে EOD দল যাবে"], e:"TPKI নির্দেশিকা: কারিগরি সংগ্রহ বিশেষজ্ঞদের কাজ; বিস্ফোরকের সন্দেহ থাকলে প্রথমে EOD দল যায়।"},
  fr:{q:"Une patrouille de la MINUKA trouve un objet suspect au bord de la route et un officier veut le rapporter aux analystes. Que faire ?", o:["Le rapporter vite, car les analystes doivent avoir l’objet en main avant qu’une autre équipe intervienne","Le photographier de près, puis le déplacer","Demander à un volontaire local de le manipuler","S’éloigner ; les équipes de déminage passent d’abord"], e:"Directives TPKI : l’acquisition technique revient aux experts, les équipes de neutralisation des explosifs passant d’abord en cas de soupçon d’explosifs."}},
 {m:"m11", a:1,
  en:{q:"Budget cuts remove half of MINUKA’s ISR capacity while drone sightings rise. What is the best first decision?", o:["Keep every requirement as it was and tell no one, because admitting gaps would damage confidence in the mission","Re-prioritise requirements and state the gaps to leaders","Use personal equipment instead","Ask a national agency to fill it in secret"], e:"Requirements must follow leadership needs. Fewer assets mean sharper priorities and honest gaps, within the same rules: no personal equipment and no clandestine shortcuts."},
  bn:{q:"বাজেট কাটছাঁটে মিনুকার ISR সক্ষমতার অর্ধেক কমে গেল, অথচ ড্রোন দেখা বাড়ছে। প্রথম সেরা সিদ্ধান্ত কী?", o:["সব চাহিদা আগের মতো রাখুন এবং কাউকে বলবেন না, কারণ ঘাটতি স্বীকার করলে মিশনের প্রতি আস্থা নষ্ট হবে","চাহিদার অগ্রাধিকার ঠিক করে নেতাদের ঘাটতি জানান","বদলে ব্যক্তিগত সরঞ্জাম ব্যবহার করুন","জাতীয় সংস্থাকে গোপনে পূরণ করতে বলুন"], e:"চাহিদা নেতৃত্বের প্রয়োজন অনুসরণ করবে। কম সম্পদ মানে তীক্ষ্ণ অগ্রাধিকার ও সৎভাবে ঘাটতি জানানো, একই নিয়মের মধ্যে: ব্যক্তিগত সরঞ্জাম বা গোপন পথ নয়।"},
  fr:{q:"Des coupes budgétaires suppriment la moitié de l’ISR de la MINUKA alors que les observations de drones augmentent. Quelle est la meilleure première décision ?", o:["Garder tous les besoins et n’en parler à personne, car admettre des lacunes nuirait à la confiance dans la mission","Revoir les priorités et signaler les lacunes aux dirigeants","Utiliser des équipements personnels","Demander à une agence nationale de combler en secret"], e:"Les besoins suivent ceux des dirigeants. Moins de moyens impose des priorités plus nettes et des lacunes assumées, dans les mêmes règles : ni équipement personnel, ni raccourci clandestin."}},
 /* ---------- m12 TRAINER ---------- */
 {m:"m12", a:1,
  en:{q:"A trainer preparing a MINUKA handout wants to cite the 2017 Santos Cruz report. How should it be cited?", o:["Give the S-number found on a forum and quote its intelligence passages directly, since secondary summaries are reliable","By title and date, without an S-number; intelligence points as second-hand","Do not mention it at all","Cite it as a Security Council resolution"], e:"No S-number was found, the text was not read, and its intelligence content is known second-hand. Cite title and date and say so."},
  bn:{q:"মিনুকার হ্যান্ডআউট তৈরির সময় একজন প্রশিক্ষক ২০১৭ সালের সান্তোস ক্রুজ প্রতিবেদন উদ্ধৃত করতে চান। কীভাবে উদ্ধৃত করবেন?", o:["ফোরামে পাওয়া S-নম্বর দিন এবং গোয়েন্দা অংশ সরাসরি উদ্ধৃত করুন, কারণ পরোক্ষ সারসংক্ষেপ নির্ভরযোগ্য","শিরোনাম ও তারিখসহ, S-নম্বর ছাড়া; গোয়েন্দা বিষয় পরোক্ষ বলে উল্লেখ","একেবারেই উল্লেখ করবেন না","নিরাপত্তা পরিষদের প্রস্তাব হিসেবে উদ্ধৃত করুন"], e:"কোনো S-নম্বর পাওয়া যায়নি, মূল পাঠ পড়া হয়নি, এবং গোয়েন্দা বিষয়বস্তু পরোক্ষভাবে জানা। শিরোনাম ও তারিখ দিন এবং তা বলুন।"},
  fr:{q:"Un formateur préparant un document pour la MINUKA veut citer le rapport Santos Cruz de 2017. Comment le citer ?", o:["Donner la cote S trouvée sur un forum et citer directement les passages sur le renseignement, car les résumés sont fiables","Par titre et date, sans cote S ; contenu sur le renseignement de seconde main","Ne pas le mentionner du tout","Le citer comme résolution du Conseil de sécurité"], e:"Aucune cote S n’a été trouvée, le texte n’a pas été lu et son contenu sur le renseignement est connu de seconde main. Citez titre et date et dites-le."}},
 {m:"m12", a:3,
  en:{q:"During a public course using the MINUKA scenario, a learner asks the trainer how to recruit and pay informants. What should the trainer do?", o:["Explain the method briefly, because learners deserve a complete picture of how such work is done elsewhere","Share a national manual after class","Invite a guest to demonstrate it","Decline, explain the rule and refer to mission guidance"], e:"The course teaches rules, limits and decisions, not tradecraft. Payment and clandestine methods are forbidden in PKI, so the trainer states the line and refers the question."},
  bn:{q:"মিনুকা পরিস্থিতি ব্যবহার করা একটি উন্মুক্ত কোর্সে একজন শিক্ষার্থী প্রশিক্ষককে জিজ্ঞাসা করলেন কীভাবে তথ্যদাতা নিয়োগ ও অর্থ দিতে হয়। প্রশিক্ষক কী করবেন?", o:["পদ্ধতিটি সংক্ষেপে ব্যাখ্যা করুন, কারণ অন্যত্র এমন কাজ কীভাবে হয় তার পূর্ণ চিত্র শিক্ষার্থীদের প্রাপ্য","ক্লাসের পরে একটি জাতীয় ম্যানুয়াল দিন","অতিথিকে দেখাতে আমন্ত্রণ জানান","প্রত্যাখ্যান করুন, নিয়ম বলুন ও মিশন নির্দেশনায় পাঠান"], e:"কোর্সটি নিয়ম, সীমা ও সিদ্ধান্ত শেখায়, কৌশল নয়। অর্থ প্রদান ও গোপন পদ্ধতি PKI-তে নিষিদ্ধ, তাই প্রশিক্ষক সীমা জানিয়ে প্রশ্নটি যথাস্থানে পাঠান।"},
  fr:{q:"Dans un cours public fondé sur le scénario MINUKA, un participant demande comment recruter et payer des informateurs. Que doit faire le formateur ?", o:["Expliquer brièvement la méthode, car les participants méritent un tableau complet de ce qui se fait ailleurs","Donner un manuel national après le cours","Inviter quelqu’un à en faire la démonstration","Refuser, expliquer la règle et renvoyer aux orientations de la mission"], e:"Le cours enseigne règles, limites et décisions, non les techniques. Le paiement et les méthodes clandestines sont interdits en PKI : le formateur rappelle la limite et renvoie la question."}},
 {m:"m12", a:0,
  en:{q:"A trainer wants to place long extracts of the 2025 Military PKI Handbook on a public MINUKA course page. What is the safer course?", o:["Paraphrase and cite; no mass reproduction without OMA’s consent","Copy freely, because every United Nations handbook is automatically free of all restrictions on reproduction","Copy, but remove the UN’s name","Sell printed copies to cover costs"], e:"The Handbook allows Member States to copy for training institutes but bars reproduction for sale or mass publication without OMA’s written consent."},
  bn:{q:"একজন প্রশিক্ষক মিনুকার একটি উন্মুক্ত কোর্স পাতায় ২০২৫ সালের সামরিক PKI হ্যান্ডবুকের দীর্ঘ অংশ দিতে চান। নিরাপদ পথ কী?", o:["নিজ ভাষায় লিখে উৎস দিন; OMA-র সম্মতি ছাড়া ব্যাপক পুনর্মুদ্রণ নয়","অবাধে কপি করুন, কারণ জাতিসংঘের প্রতিটি হ্যান্ডবুক পুনরুৎপাদনের সব বিধিনিষেধ থেকে স্বয়ংক্রিয়ভাবে মুক্ত","কপি করুন, তবে জাতিসংঘের নাম মুছে দিন","খরচ তুলতে মুদ্রিত কপি বিক্রি করুন"], e:"হ্যান্ডবুক সদস্য রাষ্ট্রকে প্রশিক্ষণ প্রতিষ্ঠানের জন্য কপি করতে দেয়, কিন্তু OMA-র লিখিত সম্মতি ছাড়া বিক্রয় বা ব্যাপক প্রকাশনার জন্য পুনরুৎপাদন নিষিদ্ধ।"},
  fr:{q:"Un formateur veut publier de longs extraits du manuel militaire de 2025 sur une page publique du cours MINUKA. Quelle est la voie la plus sûre ?", o:["Paraphraser et citer ; pas de reproduction de masse sans l’accord de l’OMA","Copier librement, car tout manuel des Nations Unies est automatiquement libre de toute restriction de reproduction","Copier en retirant le nom de l’ONU","Vendre des exemplaires pour couvrir les frais"], e:"Le manuel permet aux États Membres de copier pour leurs instituts de formation, mais interdit la reproduction pour la vente ou la publication de masse sans accord écrit de l’OMA."}},
 {m:"m12", a:2,
  en:{q:"A trainer sees that the OPKI Guidelines’ review date, 1 March 2026, has passed. What should the MINUKA class be told?", o:["They are void from that date, so the class should ignore all of their rules until a new edition is issued","They were certainly reissued in March 2026","No reissue was found; check current guidance with PICT","Review dates have no meaning at all"], e:"Several review dates have passed with no reissue found. That is absence of evidence only, so state it and check with current UN guidance."},
  bn:{q:"একজন প্রশিক্ষক দেখলেন OPKI নির্দেশিকার পর্যালোচনার তারিখ ১ মার্চ ২০২৬ পার হয়ে গেছে। মিনুকার ক্লাসকে কী বলবেন?", o:["ওই তারিখ থেকে এগুলো বাতিল, তাই নতুন সংস্করণ না আসা পর্যন্ত ক্লাস সব নিয়ম উপেক্ষা করবে","মার্চ ২০২৬-এ এগুলো নিশ্চিতভাবে পুনঃপ্রকাশিত হয়েছে","পুনঃপ্রকাশ পাওয়া যায়নি; PICT-এর সঙ্গে বর্তমান নির্দেশনা যাচাই করুন","পর্যালোচনার তারিখের কোনো অর্থই নেই"], e:"অনেক পর্যালোচনার তারিখ পার হলেও পুনঃপ্রকাশ পাওয়া যায়নি। এটি কেবল প্রমাণের অনুপস্থিতি, তাই তা বলুন এবং জাতিসংঘের বর্তমান নির্দেশনা যাচাই করুন।"},
  fr:{q:"Un formateur constate que la date de révision des Directives OPKI, le 1er mars 2026, est passée. Que dire à la classe de la MINUKA ?", o:["Elles sont nulles depuis cette date, et la classe doit ignorer toutes leurs règles jusqu’à une nouvelle édition","Elles ont assurément été rééditées en mars 2026","Aucune réédition trouvée ; vérifier les orientations actuelles auprès de PICT","Les dates de révision n’ont aucun sens"], e:"Plusieurs dates de révision sont passées sans réédition trouvée. Ce n’est qu’une absence de preuve : dites-le et vérifiez les orientations actuelles de l’ONU."}}
];
